#include <iostream>
#include <string>
struct Request { std::string method; std::string host; std::string path; };
int main() {
    const Request request{"GET", "example.invalid", "/health"};
    if (request.host.empty() || request.path.empty()) return 1;
    std::cout << request.method << ' ' << request.path << " on " << request.host << '\n';
}
